def format_bytes(n):
    if n < 10000:
        return str(n)
    if n < 1000000:
        return f"{n//1000}K"
    v = n / 1000000
    return f"{v:.1f}M"

def format_hbytes(n):
    return format_bytes(n)

def parse_log_line(line):
    m = re.match(r'^(\S+) \S+ \S+ \[(\d{2})/(\w{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2}) ([^\]]+)\] "(\S+) (\S+) ([^"]+)" (\d{3}) (\S+) "([^"]*)" "([^"]*)"', line)
    if not m:
        return None
    ip = m.group(1)
    day = int(m.group(2))
    mon_str = m.group(3)
    year = int(m.group(4))
    hour = int(m.group(5))
    minute = int(m.group(6))
    second = int(m.group(7))
    # tz = m.group(8)
    method = m.group(9)
    raw_path = m.group(10)
    status = m.group(12)
    bytes_str = m.group(13)
    referer = m.group(14)
    try:
        mon = datetime.datetime.strptime(mon_str, "%b").month
    except:
        return None
    try:
        dt = datetime.datetime(year, mon, day, hour, minute, second)
    except:
        return None
    try:
        status_int = int(status)
    except:
        return None
    if bytes_str == "-":
        return None
    try:
        bytes_int = int(bytes_str)
    except:
        return None
    known = {"GET","POST","PUT","DELETE","HEAD","OPTIONS","PATCH","CONNECT","TRACE"}
    norm_method = method if method in known else "other"
    path = raw_path.split('?')[0]
    # also strip fragment?
    path = path.split('#')[0]
    if path == "":
        path = "/"
    return {
        "ip": ip,
        "datetime": dt,
        "date_str": f"{year:04d}/{mon:02d}/{day:02d}",
        "time_str": f"{hour:02d}:{minute:02d}:{second:02d}",
        "method": norm_method,
        "raw_method": method,
        "path": path,
        "raw_path": raw_path,
        "status": status_int,
        "status_str": status,
        "bytes": bytes_int,
        "referer": referer,
        "raw_line": line.rstrip("\n"),
    }

# ----- Filter parsing for path/ip/referer -----
def split_top_level(s, delim):
    parts=[]
    depth=0
    last=0
    i=0
    L=len(s)
    dlen=len(delim)
    while i < L:
        ch=s[i]
        if ch=='(':
            depth+=1
        elif ch==')':
            if depth>0:
                depth-=1
        if depth==0 and s[i:i+dlen]==delim:
            parts.append(s[last:i])
            last=i+dlen
            i+=dlen
            continue
        i+=1
    parts.append(s[last:])
    return parts

def eval_expr(expr, target, match_func):
    expr=expr.strip()
    if expr=="":
        return True
    # outer parentheses enclosing whole expr
    if expr.startswith('(') and expr.endswith(')'):
        depth=0
        for i,ch in enumerate(expr):
            if ch=='(':
                depth+=1
            elif ch==')':
                depth-=1
                if depth==0:
                    if i==len(expr)-1:
                        inner=expr[1:-1].strip()
                        return eval_expr(inner, target, match_func)
                    else:
                        break
    if expr.startswith('!'):
        rest=expr[1:].strip()
        return not eval_expr(rest, target, match_func)
    parts = split_top_level(expr, " | ")
    if len(parts)>1:
        return any(eval_expr(p, target, match_func) for p in parts)
    parts = split_top_level(expr, " & ")
    if len(parts)>1:
        return all(eval_expr(p, target, match_func) for p in parts)
    # leaf
    try:
        return match_func(expr, target)
    except re.error as e:
        raise ValueError(f"InvalidRegex({e})")

def str_filter_match(filter_str, target):
    if filter_str is None:
        return True
    parts = split_top_level(filter_str, ",")
    for part in parts:
        part=part.strip()
        if part=="":
            continue
        def mf(pat, tgt):
            return re.search(pat, tgt) is not None
        try:
            if not eval_expr(part, target, mf):
                return False
        except re.error as e:
            raise ValueError(f"StrFilter(InvalidRegex({e}))")
        except ValueError as e:
            # Check if it's regex error already formatted
            msg=str(e)
            if "InvalidRegex" in msg:
                raise
            else:
                raise ValueError(f"StrFilter(InvalidRegex(Syntax(\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nregex parse error:\n    {msg}\n)))")
    return True

def path_filter_match(f, path):
