def format_bytes(n):
    if n < 10000:
        return str(n)
    if n < 1000000:
        return f"{n//1000}K"
    return f"{n/1000000:.1f}M"

def is_resource(path):
    # known resource extensions
    lower=path.lower()
    resources=[".png",".jpg",".jpeg",".gif",".ico",".css",".js",".svg",".woff2",".webp"]
    for ext in resources:
        if lower.endswith(ext):
            return True
    return False

def parse_log_line(line):
    m = re.match(r'^(\S+) \S+ \S+ \[(\d{2})/(\w{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2}) ([^\]]+)\] "(\S+) (\S+) ([^"]+)" (\d{3}) (\S+) "([^"]*)" "([^"]*)"', line)
    if not m:
        return None
    ip=m.group(1)
    day=int(m.group(2)); mon_str=m.group(3); year=int(m.group(4))
    hour=int(m.group(5)); minute=int(m.group(6)); second=int(m.group(7))
    method=m.group(9); raw_path=m.group(10)
    status=m.group(12); bytes_str=m.group(13); referer=m.group(14)
    try:
        mon=datetime.datetime.strptime(mon_str, "%b").month
    except:
        return None
    try:
        dt=datetime.datetime(year, mon, day, hour, minute, second)
    except:
        return None
    try:
        status_int=int(status)
    except:
        return None
    if bytes_str=="-":
        return None
    try:
        bytes_int=int(bytes_str)
    except:
        return None
    known={"GET","POST","PUT","DELETE","HEAD","OPTIONS","PATCH","CONNECT","TRACE"}
    norm=method if method in known else "other"
    path=raw_path.split('?')[0].split('#')[0]
    if path=="":
        path="/"
    return {"ip":ip,"datetime":dt,"date_str":f"{year:04d}/{mon:02d}/{day:02d}","time_str":f"{hour:02d}:{minute:02d}:{second:02d}","method":norm,"raw_method":method,"path":path,"raw_path":raw_path,"status":status_int,"status_str":status,"bytes":bytes_int,"referer":referer,"raw_line":line.rstrip("\n")}

# string filters
def split_top_level(s, delim):
    parts=[]; depth=0; last=0; i=0; L=len(s); dlen=len(delim)
    while i<L:
        ch=s[i]
        if ch=='(':
            depth+=1
        elif ch==')':
            if depth>0: depth-=1
        if depth==0 and s[i:i+dlen]==delim:
            parts.append(s[last:i]); last=i+dlen; i+=dlen; continue
        i+=1
    parts.append(s[last:])
    return parts

def eval_expr(expr, target, match_func):
    expr=expr.strip()
    if expr=="":
        return True
    if expr.startswith('(') and expr.endswith(')'):
        depth=0
        for i,ch in enumerate(expr):
            if ch=='(':
                depth+=1
            elif ch==')':
                depth-=1
                if depth==0:
                    if i==len(expr)-1:
                        inner=expr[1:-1].strip()
                        return eval_expr(inner, target, match_func)
                    else:
                        break
    if expr.startswith('!'):
        rest=expr[1:].strip()
        return not eval_expr(rest, target, match_func)
    parts=split_top_level(expr, " | ")
    if len(parts)>1:
        return any(eval_expr(p,target,match_func) for p in parts)
    parts=split_top_level(expr, " & ")
    if len(parts)>1:
        return all(eval_expr(p,target,match_func) for p in parts)
    try:
        return match_func(expr, target)
    except re.error as e:
        raise ValueError(f"InvalidRegex({e})")

def str_filter_match(filter_str, target):
    if filter_str is None:
        return True
    parts=split_top_level(filter_str, ",")
    for part in parts:
        part=part.strip()
        if part=="":
            continue
        def mf(pat,tgt):
            return re.search(pat,tgt) is not None
        try:
            if not eval_expr(part, target, mf):
                return False
        except re.error as e:
            raise ValueError(f"StrFilter(InvalidRegex(Syntax(\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nregex parse error:\n    {e}\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n)))")
        except ValueError as e:
            msg=str(e)
            if "InvalidRegex" in msg:
                raise
            raise ValueError(f"StrFilter(InvalidRegex({msg}))")
    return True

def path_filter_match(f,p): return str_filter_match(f,p)
def ip_filter_match(f,ip): return str_filter_match(f,ip)
def referer_filter_match(f,r): return str_filter_match(f,r)

def method_filter_match(filter_str, method_norm, raw_method):
    if filter_str is None:
        return True
    parts=[p.strip() for p in filter_str.split(',') if p.strip()!=""]
    for part in parts:
        neg=False
        if part.startswith('!'):
            neg=True; part=part[1:]
        if part.lower()=="other":
            matched=(method_norm=="other")
        elif part.lower()=="none":
            matched=False
        else:
            matched=(part==raw_method) or (part==method_norm)
        if neg:
            matched=not matched
        if not matched:
            return False
    return True

def status_filter_match(filter_str, status_int):
    if filter_str is None:
        return True
    tokens=[t.strip() for t in filter_str.split(',') if t.strip()!=""]
    positives=[]; negatives=[]
    for tok in tokens:
        neg=False
        if tok.startswith('!'):
            neg=True; tok=tok[1:]
        (negatives if neg else positives).append(tok)
    def validate(tok):
        if tok.endswith("xx"):
            if len(tok)!=3 or tok[1]!="x" or tok[2]!="x":
                raise ValueError(f"StatusFilter(ParseInt(ParseIntError {{ kind: InvalidDigit }}))")
            if tok not in ["1xx","2xx","3xx","4xx","5xx"]:
                raise ValueError(f"StatusFilter(ParseInt(ParseIntError {{ kind: InvalidDigit }}))")
            if tok!=tok.lower():
                raise ValueError(f"StatusFilter(ParseInt(ParseIntError {{ kind: InvalidDigit }}))")
        elif "-" in tok:
            parts=tok.split("-")
            if len(parts)!=2:
                raise ValueError(f"StatusFilter(ParseInt(ParseIntError {{ kind: InvalidDigit }}))")
            try: a=int(parts[0]); b=int(parts[1])
            except: raise ValueError(f"StatusFilter(ParseInt(ParseIntError {{ kind: InvalidDigit }}))")
        else:
            try: v=int(tok)
            except: raise ValueError(f"StatusFilter(ParseInt(ParseIntError {{ kind: InvalidDigit }}))")
    for tok in positives+negatives:
        validate(tok)
    def matches(tok,st):
        if tok.endswith("xx"):
            return st//100==int(tok[0])
        elif "-" in tok:
            a,b=map(int,tok.split("-")); return a<=st<=b
        else:
            return st==int(tok)
    in_pos=any(matches(tok,status_int) for tok in positives) if positives else True
    if not in_pos:
        return False
    if any(matches(tok,status_int) for tok in negatives):
        return False
    return True

def parse_date_spec(s):
    s=s.strip()
    if s=="":
        raise ValueError("IntExpected(ParseIntError { kind: Empty })")
    if 'T' in s:
        date_part,time_part=s.split('T',1)
    else:
        date_part,time_part=s,None
    date_part=date_part.strip(); time_part=time_part.strip() if time_part else None
    if date_part=="":
        raise ValueError("IntExpected(ParseIntError { kind: Empty })")
    dparts=date_part.split('/')
    try:
        dnums=[int(p) for p in dparts if p!=""]
    except:
        raise ValueError("IntExpected(ParseIntError { kind: Empty })")
    if len(dnums)==0:
        raise ValueError("IntExpected(ParseIntError { kind: Empty })")
    year=None; month=None; day=None; has_year=False; has_month=False; has_day=False
    if len(dnums)==3:
        year,month,day=dnums; has_year=has_month=has_day=True
    elif len(dnums)==2:
        if dnums[0]>=1000:
            year,month=dnums; has_year=has_month=True
        else:
            month,day=dnums; has_month=has_day=True
    elif len(dnums)==1:
        year=dnums[0]; has_year=True
    else:
        raise ValueError("IntExpected(ParseIntError { kind: Empty })")
    if has_month and month is not None and not (1 <= month <= 12):
        raise ValueError("IntExpected(ParseIntError { kind: PosOverflow })")
    if has_day and day is not None and not (1 <= day <= 31):
        raise ValueError("IntExpected(ParseIntError { kind: PosOverflow })")
    th=None; tm=None; ts=None; has_time=False; has_sec=False
    if time_part is not None:
        if time_part=="":
            raise ValueError("IntExpected(ParseIntError { kind: Empty })")
        tparts=time_part.split(':')
        try:
            tnums=[int(p) for p in tparts if p!=""]
        except:
            raise ValueError("IntExpected(ParseIntError { kind: Empty })")
        if len(tnums)>=1:
            th=tnums[0]; has_time=True
        if len(tnums)>=2:
            tm=tnums[1]
        if len(tnums)>=3:
            ts=tnums[2]; has_sec=True
        if len(tnums)>3:
            raise ValueError("IntExpected(ParseIntError { kind: Empty })")
        if th is not None and not (0 <= th <= 23):
            raise ValueError("IntExpected(ParseIntError { kind: PosOverflow })")
        if tm is not None and not (0 <= tm <= 59):
            raise ValueError("IntExpected(ParseIntError { kind: PosOverflow })")
        if ts is not None and not (0 <= ts <= 59):
            raise ValueError("IntExpected(ParseIntError { kind: PosOverflow })")
    if not has_year and has_month and has_day:
        return {"type":"md","month":month,"day":day,"hour":th,"minute":tm,"second":ts,"has_time":has_time,"has_sec":has_sec}
    elif not has_year:
        raise ValueError("IntExpected(ParseIntError { kind: Empty })")
    else:
        if not has_month:
            start=datetime.datetime(year,1,1,0,0,0); end=datetime.datetime(year,12,31,23,59,59)
        elif not has_day:
            last_day=calendar.monthrange(year,month)[1]
            start=datetime.datetime(year,month,1,0,0,0); end=datetime.datetime(year,month,last_day,23,59,59)
        else:
            try:
                start=datetime.datetime(year,month,day,0,0,0); end=datetime.datetime(year,month,day,23,59,59)
            except ValueError as e:
                raise ValueError(str(e))
        if has_time:
            if has_day:
                h=th if th is not None else 0; m=tm if tm is not None else 0; s=ts if ts is not None else 0
                start=datetime.datetime(year,month,day,h,m,s)
                if has_sec:
                    end=start
                elif tm is not None:
                    end=datetime.datetime(year,month,day,h,m,59)
                elif th is not None:
                    end=datetime.datetime(year,month,day,h,59,59)
                else:
                    end=start
        return {"type":"abs","start":start,"end":end}

def date_filter_match(filter_str, dt):
    if filter_str is None:
        return True
    neg=False; op=None; rest=filter_str
    if rest.startswith('!'):
        neg=True; rest=rest[1:]
    elif rest.startswith('>'):
        op='>'; rest=rest[1:]
    elif rest.startswith('<'):
        op='<'; rest=rest[1:]
    rest=rest.strip()
    is_range=False; left_spec=right_spec=None
    if op is None:
        if '-' in rest:
            for idx in range(len(rest)):
                if rest[idx]=='-':
                    if idx==0 or idx==len(rest)-1:
                        continue
                    lc=rest[:idx]; rc=rest[idx+1:]
                    try:
                        parse_date_spec(lc); parse_date_spec(rc)
                        left_spec=lc; right_spec=rc; is_range=True; break
                    except:
                        continue
    else:
        pass
    if neg and not is_range and '-' in rest:
        for idx in range(len(rest)):
            if rest[idx]=='-':
                if idx==0 or idx==len(rest)-1: continue
                lc=rest[:idx]; rc=rest[idx+1:]
                try:
                    parse_date_spec(lc); parse_date_spec(rc)
                    left_spec=lc; right_spec=rc; is_range=True; break
                except:
                    continue
    if is_range:
        try:
            linfo=parse_date_spec(left_spec); rinfo=parse_date_spec(right_spec)
        except Exception as e:
            raise ValueError(f"DateTime({e})") if "DateTime" not in str(e) else e
        if linfo["type"]=="abs" and rinfo["type"]=="abs":
            start=linfo["start"]; end=rinfo["end"]
            matched = start <= dt <= end
        elif linfo["type"]=="md" and rinfo["type"]=="md":
            cur=(dt.month,dt.day); s=(linfo["month"],linfo["day"]); e=(rinfo["month"],rinfo["day"])
            if s<=e:
                matched = s<=cur<=e
            else:
                matched = cur>=s or cur<=e
        else:
            matched=False
        if neg:
            matched=not matched
        return matched
    else:
        spec_str=rest
        if spec_str=="":
            raise ValueError("DateTime(IntExpected(ParseIntError { kind: Empty }))")
        try:
            info=parse_date_spec(spec_str)
        except Exception as e:
            if "DateTime" in str(e):
                raise
            raise ValueError(f"DateTime({e})")
        if info["type"]=="abs":
            start=info["start"]; end=info["end"]
            if op is None:
                matched = start <= dt <= end
                if neg:
                    matched=not matched
                return matched
            elif op==">":
                return dt > end
            elif op=="<":
                return dt < start
        elif info["type"]=="md":
            if op is None:
                if neg:
                    if info["has_time"]:
                        if dt.month==info["month"] and dt.day==info["day"]:
                            h=info["hour"] if info["hour"] is not None else 0
                            m=info["minute"] if info["minute"] is not None else 0
                            s=info["second"] if info["second"] is not None else 0
                            if info["has_sec"]:
                                matched_time=(dt.hour==h and dt.minute==m and dt.second==s)
                            elif info["minute"] is not None:
                                matched_time=(dt.hour==h and dt.minute==m)
                            elif info["hour"] is not None:
                                matched_time=(dt.hour==h)
                            else:
                                matched_time=False
                            return not matched_time
                        else:
                            return True
                    else:
                        return not (dt.month==info["month"] and dt.day==info["day"])
                else:
                    if dt.month==info["month"] and dt.day==info["day"]:
                        if info["has_time"]:
                            h=info["hour"] if info["hour"] is not None else 0
                            m=info["minute"] if info["minute"] is not None else 0
                            s=info["second"] if info["second"] is not None else 0
                            if info["has_sec"]:
                                return dt.hour==h and dt.minute==m and dt.second==s
                            elif info["minute"] is not None:
                                return dt.hour==h and dt.minute==m
                            elif info["hour"] is not None:
                                return dt.hour==h
                            else:
                                return True
                        else:
                            return True
                    else:
                        return False
            elif op==">":
                cur=(dt.month,dt.day); spec=(info["month"],info["day"]); return cur>spec
            elif op=="<":
                cur=(dt.month,dt.day); spec=(info["month"],info["day"]); return cur<spec
        return False

def parse_time_spec(s):
    parts=s.split(':')
    if len(parts)==0 or len(parts)>3:
        raise ValueError("Invalid")
    try:
        h=int(parts[0]); m=int(parts[1]) if len(parts)>=2 else 0; sec=int(parts[2]) if len(parts)>=3 else 0
    except:
        raise ValueError("Invalid")
    if not (0<=h<=23 and 0<=m<=59 and 0<=sec<=59):
        raise ValueError("Invalid")
    return (h,m,sec)

def time_filter_match(filter_str, dt):
    if filter_str is None:
        return True
    s=filter_str.strip()
    if s=="":
        raise ValueError("TimeFilter(InvalidFormat)")
    neg=False; op=None
    if s.startswith('!'):
        neg=True; s=s[1:]
    elif s.startswith('>'):
        op='>'; s=s[1:]
    elif s.startswith('<'):
        op='<'; s=s[1:]
    if '-' in s and op is None and not neg:
        left,right=s.split('-',1)
        left=left.strip(); right=right.strip()
        try:
            lt=parse_time_spec(left); rt=parse_time_spec(right)
        except:
            raise ValueError("TimeFilter(InvalidFormat)")
        cur=dt.hour*3600+dt.minute*60+dt.second
        lsec=lt[0]*3600+lt[1]*60+lt[2]; rsec=rt[0]*3600+rt[1]*60+rt[2]
        if lsec<=rsec:
            matched=lsec<=cur<=rsec
        else:
            matched=cur>=lsec or cur<=rsec
        return matched
    elif '-' in s and (op is not None or neg):
        raise ValueError("TimeFilter(InvalidFormat)")
    else:
        if neg:
            raise ValueError("TimeFilter(InvalidFormat)")
        if op is not None:
            try:
                tsp=parse_time_spec(s)
            except:
                raise ValueError("TimeFilter(InvalidFormat)")
            cur=dt.hour*3600+dt.minute*60+dt.second; tsec=tsp[0]*3600+tsp[1]*60+tsp[2]
            if op==">":
                return cur>tsec
            elif op=="<":
                return cur<tsec
        else:
            raise ValueError("TimeFilter(InvalidFormat)")

def is_access_log_name(name):
    if name=="access.log":
        return True
    if name.startswith("access.log."):
        suffix=name[len("access.log"):]
        if suffix.startswith("."):
            return True
        return False
    return False

def discover_files(paths, no_name_check):
    file_list=[]
    for p in paths:
        if os.path.isfile(p):
            file_list.append(p)
        elif os.path.isdir(p):
            for root, dirs, files in os.walk(p):
                for f in files:
                    full=os.path.join(root,f)
                    if no_name_check:
                        file_list.append(full)
                    else:
                        if is_access_log_name(f):
                            file_list.append(full)
        else:
            raise FileNotFoundError(f'PathNotFound("{p}")')
    return file_list

def read_lines(path):
    if path.endswith('.gz'):
        try:
            with gzip.open(path, 'rt', encoding='utf-8', errors='ignore') as f:
                for line in f:
                    yield line
        except:
            return
    else:
        try:
            with open(path,'r', encoding='utf-8', errors='ignore') as f:
                for line in f:
                    yield line
        except:
            return

# field handling
def canonical(s):
    s=s.strip().lower()
    if s in ["date","d","dates"]: return "date"
    if s in ["time","t","times"]: return "time"
    if s in ["method","m","methods"]: return "method"
    if s in ["status","s","statuses"]: return "status"
    if s in ["ip","i","ips","remote","address"]: return "ip"
    if s in ["ref","r","referer","referrers","referrer"]: return "ref"
    if s in ["path","p","paths"]: return "path"
    if s in ["all","a"]: return "all"
    return None

def parse_fields(arg):
    default=["date","status","ref","path"]
    all_fields=["date","time","method","status","ip","ref","path"]
    if arg is None:
        return default
    arg=arg.strip()
    if arg=="":
        return []
    low=arg.lower().strip()
    if low.startswith('+') or low.startswith('-'):
        base=default.copy()
        tokens=[]; i=0
        while i<len(low):
            if low[i] in '+-':
                sign=low[i]; i+=1
                start=i
                while i<len(low) and low[i] not in '+-,':
                    i+=1
                field=low[start:i].strip()
                if i<len(low) and low[i]==',':
                    i+=1
                tokens.append((sign, field))
            else:
                i+=1
        for sign, fr in tokens:
            if not fr: continue
            can=canonical(fr)
            if can is None: continue
            if can=="all": continue
            if sign=='+':
                if can in base:
                    base.remove(can)
                    base.append(can)
                else:
                    base.append(can)
            else:
                if can in base:
                    base.remove(can)
        return base
    elif low.startswith('all') or low=='a' or low.startswith('a-') or low.startswith('a+'):
        base=all_fields.copy()
        if low.startswith('all'):
            rem=low[3:]
        else:
            rem=low[1:]
        rem=rem.strip()
        if not rem:
            return base
        tokens=[]; i=0
        while i<len(rem):
            if rem[i] in '+-':
                sign=rem[i]; i+=1
                start=i
                while i<len(rem) and rem[i] not in '+-,':
                    i+=1
                field=rem[start:i].strip()
                if i<len(rem) and rem[i]==',':
                    i+=1
                tokens.append((sign, field))
            elif rem[i]==',':
                i+=1
            else:
                i+=1
        for sign, fr in tokens:
            if not fr: continue
            can=canonical(fr)
            if can is None: continue
            if sign=='+':
                if can in base:
                    base.remove(can)
                    base.append(can)
                else:
                    base.append(can)
            else:
                if can in base:
                    base.remove(can)
        return base
    else:
        tmp=low.replace('+', ',')
        parts=[p.strip() for p in tmp.split(',') if p.strip()!='']
        result=[]
        for p in parts:
            can=canonical(p)
            if can and can!="all":
                if can not in result:
                    result.append(can)
            elif can=="all":
                for f in all_fields:
                    if f not in result:
                        result.append(f)
        return result

# helpers for rendering
def wrap_text(text, width):
    lines=[]
    while len(text)>width:
        lines.append(text[:width])
        text=text[width:]
    lines.append(text)
    return lines

def compute_days(entries):
    dates=sorted(set(e["date_str"] for e in entries))
    # convert to datetime for sorting correctly: dates are YYYY/MM/DD lexical sort works
    return dates

def render_table(headers, rows, col_widths=None):
    # headers: list of strings
    # rows: list of lists (each row is list of strings)
    # col_widths: optional list of ints
    if not rows and not headers:
        return ""
    n=len(headers)
    if col_widths is None:
        col_widths=[len(h) for h in headers]
        for row in rows:
            for i,cell in enumerate(row):
                if i>=len(col_widths): continue
                # cell may contain newline? not here
                col_widths[i]=max(col_widths[i], len(str(cell).split("\n")[0]))
        # ensure minimum widths
    # build border
    def border(left,mid,right):
        s=left
        for i,w in enumerate(col_widths):
            s+='─'*(w+2)
            if i<n-1:
                s+=mid
            else:
                s+=right
        return s
    out=[]
    out.append(border('┌','┬','┐'))
    # header row
    hrow='│'
    for i,h in enumerate(headers):
        w=col_widths[i]
        hrow+=f' {h:^{w}} │'
    out.append(hrow)
    out.append(border('├','┼','┤'))
    for row in rows:
        # row may have wrapping? assume already wrapped
        r='│'
        for i,cell in enumerate(row):
            w=col_widths[i]
            # align: numbers right, text left? We'll just left for path/referrer, center for others?
            # For simplicity, left align for path/ref/ip, right for numeric
            # Detect numeric: if cell strips is digits or contains %
            cell_str=str(cell)
            if re.match(r'^[\d,]+$|^[\d.]+%?$', cell_str.replace(' ','').replace(',','')) or re.match(r'^\d+$', cell_str.strip()):
                # right align
                r+=f' {cell_str:>{w}} │'
            else:
                r+=f' {cell_str:<{w}} │'
        out.append(r)
    out.append(border('└','┴','┘'))
    return "\n".join(out)

# main logic
def main():
    argv=sys.argv[1:]
    # quick help/version handling before parsing
    # We need to handle --help and --version as independent of other args
    # Also need --color handling for help? But help always colored per earlier.
    # Detect help/version in argv
    # Help triggers if --help in argv
    if '--help' in argv:
        sys.stdout.write(HELP_TEXT)
        sys.exit(0)
    if '--version' in argv:
        sys.stdout.write(f"rhit {VERSION}\n")
        sys.exit(0)
    # Define parser
    import argparse
    parser=argparse.ArgumentParser(prog='rhit', add_help=False)
    parser.add_argument('--color', dest='color', default='auto', choices=['auto','yes','no'])
    parser.add_argument('-k','--key', dest='key', default='hits')
    parser.add_argument('-l','--length', dest='length', default='1')
    parser.add_argument('-f','--fields', dest='fields', default=None)
    parser.add_argument('-c','--changes', dest='changes', action='store_true')
    parser.add_argument('-d','--date', dest='date', default=None)
    parser.add_argument('-i','--ip', dest='ip', default=None)
    parser.add_argument('-m','--method', dest='method', default=None)
    parser.add_argument('-p','--path', dest='path', default=None)
    parser.add_argument('-r','--referer', dest='referer', default=None)
    parser.add_argument('-s','--status', dest='status', default=None)
    parser.add_argument('-t','--time', dest='time', default=None)
    parser.add_argument('-a','--all', dest='all', action='store_true')
    parser.add_argument('--no-name-check', dest='no_name_check', action='store_true')
    parser.add_argument('-o','--output', dest='output', default='tables')
    parser.add_argument('--silent-load', dest='silent_load', action='store_true')
    parser.add_argument('files', nargs='*')
    # custom error handling
    orig_error=parser.error
    def custom_error(msg):
        # map to original format
        if "unrecognized arguments" in msg:
            m=re.search(r"unrecognized arguments: (.+)", msg)
            arg=m.group(1).split()[0] if m else ""
            sys.stderr.write(f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: executable [OPTIONS] [FILES]...\n")
            sys.exit(2)
        elif "expected one argument" in msg:
            m=re.search(r"argument (.+): expected", msg)
            arg=m.group(1) if m else ""
            # try to find long name
            # arg like '-f/--fields'
            long=arg
            if '/' in arg:
                parts=arg.split('/')
                long=parts[-1]
            # map to display with placeholder
            placeholder=long.strip('-').upper()
            # For --fields, placeholder is FIELDS
            # For --date etc.
            sys.stderr.write(f"error: a value is required for '{long} <{placeholder}>' but none was supplied\n\nFor more information, try '--help'.\n")
            sys.exit(2)
        else:
            sys.stderr.write(f"error: {msg}\n\nUsage: executable [OPTIONS] [FILES]...\n")
            sys.exit(2)
    parser.error=custom_error
    try:
        args=parser.parse_args(argv)
    except SystemExit as e:
        if e.code!=0:
            raise
        sys.exit(e.code)
    # validate key
    if args.key.lower() not in ['hits','bytes','h','b']:
        sys.stderr.write(f"error: invalid value '{args.key}' for '--key <KEY>': unrecognized key \"{args.key}\"\n")
        sys.exit(2)
    key='hits' if args.key.lower() in ['hits','h'] else 'bytes'
    # validate length
    try:
        length=int(args.length)
    except:
        sys.stderr.write(f"error: invalid value '{args.length}' for '--length <LENGTH>': invalid digit found in string\n")
        sys.exit(2)
    # validate output
    out_map={'tables':'tables','table':'tables','t':'tables','csv':'csv','c':'csv','json':'json','j':'json','raw':'raw','r':'raw'}
    out_low=args.output.lower()
    if out_low not in out_map:
        sys.stderr.write(f"error: invalid value '{args.output}' for '--output <OUTPUT>': unrecognized output \"{args.output}\"\n")
        sys.exit(2)
    output=out_map[out_low]
    # validate color (argparse already does but we removed choices? now we have choices, so it will be validated via custom_error)
    # But we set choices, so invalid will be caught as invalid choice -> custom_error will produce generic, not specific. So handle manual validation instead.
    # Since we set choices, manual not needed. But we removed choices? We kept choices, so custom_error will handle.
    # For --color invalid, original message: error: invalid value 'maybe' for '--color <color>' \n  [possible values: auto, yes, no]
